shell_commands:
node --input-type=module -e "
import ajv8 from 'ajv';
import {createRequire} from 'node:module';
const require = createRequire(import.meta.url);
const ajv6 = require('./node_modules/eslint/node_modules/ajv');

for (const [label, Ctor] of [['ajv8', ajv8], ['ajv6', ajv6]]) {
  const a = new Ctor({strict: false, validateFormats: false, format: false, allErrors: true, logger: false});
  console.log('===', label, '===');
  // 1. broken schema
  try { a.compile({type: 'bogus'}); console.log('broken: DID NOT THROW'); } catch (e) { console.log('broken threw:', String(e)); }
  // 2. async schema
  try { const fn = a.compile({\$async: true, type: 'object'}); console.log('async compiled:', typeof fn); } catch (e) { console.log('async threw:', String(e)); }
  // 3. missing required top-level and nested, wrong type top-level and nested, enum, root additionalProperties: false, array item
  const v = a.compile({
    type: 'object',
    properties: {
      location: {type: 'string'},
      units: {type: 'string', enum: ['c', 'f']},
      nested: {
        type: 'object',
        properties: { code: {type: 'number'} },
        required: ['code']
      },
      items: {
        type: 'array',
        items: { type: 'string' }
      }
    },
    required: ['location'],
    additionalProperties: false
  });
  v({units: 'k', nested: {}, items: [123], extra: 'secret'});
  console.log('errors1:', v.errors);
  const v2 = a.compile({
    type: 'object',
    properties: { nested: { type: 'object', properties: { code: {type: 'string'} }, required: ['code'] } }
  });
  v2({nested: {code: 42}});
  console.log('errors2:', v2.errors);
}
"
